import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { shadcnSeparatorClassesByOrientation } from "./view";
import type { SeparatorOrientation } from "./view";

export {
  shadcnHorizontalSeparatorClasses,
  shadcnSeparatorBaseClasses,
  shadcnSeparatorClassesByOrientation,
  shadcnVerticalSeparatorClasses,
} from "./view";

export type { SeparatorOrientation };

export type SeparatorStyle = Readonly<Record<string, string>>;

export type ViewConfig = Readonly<{
  orientation?: SeparatorOrientation;
  className?: string | undefined;
  style?: SeparatorStyle | undefined;
  decorative?: boolean | undefined;
}>;

export const view = <ParentMessage>({
  className,
  decorative = true,
  orientation = "horizontal",
  style,
}: ViewConfig = {}): Html => {
  const h = html<ParentMessage>();
  const cn = [shadcnSeparatorClassesByOrientation(orientation), className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.div(
    [
      decorative
        ? h.Attribute("role", "none")
        : h.Attribute("role", "separator"),
      ...(decorative ? [] : [h.Attribute("aria-orientation", orientation)]),
      h.DataAttribute("slot", "separator"),
      h.DataAttribute("orientation", orientation),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn),
    ],
    []
  );
};

export type SeparatorOrientation = "horizontal" | "vertical";

export const shadcnSeparatorBaseClasses =
  "shrink-0 bg-border data-horizontal:h-px data-horizontal:w-full data-vertical:w-px data-vertical:self-stretch";

export const shadcnHorizontalSeparatorClasses = shadcnSeparatorBaseClasses;

export const shadcnVerticalSeparatorClasses = shadcnSeparatorBaseClasses;

export const shadcnSeparatorClassesByOrientation = (
  _orientation: SeparatorOrientation = "horizontal"
): string => shadcnSeparatorBaseClasses;

import { describe, expect, test } from "vitest";

import * as Separator from "./index";

describe("shadcn Separator registry view", () => {
  test("matches the current shadcn separator class contract", () => {
    expect(Separator.view).toBeTypeOf("function");
    expect(
      Separator.shadcnSeparatorClassesByOrientation("vertical")
    ).toBe(Separator.shadcnSeparatorBaseClasses);
    expect(Separator.shadcnSeparatorBaseClasses).toContain("bg-border");
    expect(Separator.shadcnSeparatorBaseClasses).toContain(
      "data-vertical:self-stretch"
    );
  });
});
